16	package org.traccar.protocol;
17	
18	import io.netty.channel.Channel;
19	import org.traccar.AbstractWireDecoder;
20	import org.traccar.session.UnitSession;
21	import org.traccar.NetworkMessage;
22	import org.traccar.Protocol;
23	import org.traccar.helper.DateBuilder;
24	import org.traccar.helper.FieldCursor;
25	import org.traccar.helper.GrammarComposer;
26	import org.traccar.model.Command;
27	import org.traccar.model.Position;
28	
29	import java.net.SocketAddress;
30	import java.util.Arrays;
31	import java.util.regex.Pattern;
32	
33	public class Xrb28ProtocolDecoder extends AbstractWireDecoder {
34	
35	    private String pendingCommand;
36	
37	    public void setPendingCommand(String pendingCommand) {
38	        this.pendingCommand = pendingCommand;
39	    }
40	
41	    public Xrb28ProtocolDecoder(Protocol protocol) {
42	        super(protocol);
43	    }
44	
45	    private static final Pattern PATTERN = new GrammarComposer()
46	            .text("*")
47	            .expression("....,")
48	            .expression("..,")                   // vendor
49	            .number("d{15},")                    // imei
50	            .number("d{12},").optional()         // time
51	            .expression("..,")                   // type
52	            .number("[01],")                     // reserved
53	            .number("(dd)(dd)(dd).d+,")          // time (hhmmss)
54	            .expression("([AV]),")               // validity
55	            .number("(dd)(dd.d+),")              // latitude
56	            .expression("([NS]),")
57	            .number("(d{2,3})(dd.d+),")          // longitude
58	            .expression("([EW]),")
59	            .number("(d+),")                     // satellites
60	            .number("(d+.d+),")                  // hdop
61	            .number("(dd)(dd)(dd),")             // date (ddmmyy)
62	            .number("(-?d+.?d*),")               // altitude
63	            .expression(".,")                    // height unit
64	            .expression(".#")                    // mode
65	            .compile();
66	
67	    @Override
68	    protected Object decode(
69	            Channel channel, SocketAddress remoteAddress, Object msg) throws Exception {
70	
71	        String sentence = (String) msg;
72	        String[] values = sentence.replaceAll("#$", "").split(",");
73	
74	        int index = 0;
75	        String header = values[index++];
76	        String vendor = values[index++];
77	
78	        String imei = values[index++];
79	        UnitSession deviceSession = resolveUnitSession(channel, remoteAddress, imei);
80	        if (deviceSession == null) {
81	            return null;
82	        }
83	
84	        String time;
85	        if (values[index].length() == 12) {
86	            time = values[index++];
87	        } else {
88	            time = null;
89	        }
90	
91	        String type = values[index++];
92	        if (channel != null) {
93	            StringBuilder response = new StringBuilder("\u00ff\u00ff");
94	            response.append(header.replaceAll("R$", "S")).append(',');
95	            response.append(vendor).append(',');
96	            response.append(imei).append(',');
97	            if (time != null) {
98	                response.append(time).append(',');
99	            }
100	            if (type.matches("L0|L1|W0|E1")) {
101	                response.append(type).append("#\n");
102	                channel.write(new NetworkMessage(response.toString(), remoteAddress));
103	            } else if (type.equals("R0") && pendingCommand != null) {
104	                String command = pendingCommand.equals(Command.TYPE_ALARM_ARM) ? "L1" : "L0";
105	                response.append(command);
106	                String[] remaining = Arrays.copyOfRange(values, index, values.length);
107	                response.append(String.join(",", remaining));
108	                response.append("#\n");
109	                channel.write(new NetworkMessage(response.toString(), remoteAddress));
110	                pendingCommand = null;
111	            }
112	        }
113	
114	        if (!type.startsWith("D")) {
115	
116	            Position position = new Position(wireName());
117	            position.setDeviceId(deviceSession.getDeviceId());
118	
119	            getLastLocation(position, null);
120	
121	            switch (type) {
122	                case "Q0" -> {
123	                    position.set(Position.KEY_BATTERY, Integer.parseInt(values[index++]) / 100.0);
124	                    position.set(Position.KEY_BATTERY_LEVEL, Integer.parseInt(values[index++]));
125	                    position.set(Position.KEY_RSSI, Integer.parseInt(values[index++]));
126	                }
127	                case "H0" -> {
128	                    position.set(Position.KEY_BLOCKED, Integer.parseInt(values[index++]) > 0);
129	                    position.set(Position.KEY_BATTERY, Integer.parseInt(values[index++]) / 100.0);
130	                    position.set(Position.KEY_RSSI, Integer.parseInt(values[index++]));
131	                    position.set(Position.KEY_BATTERY_LEVEL, Integer.parseInt(values[index++]));
132	                }
133	                case "W0" -> {
134	                    switch (Integer.parseInt(values[index++])) {
135	                        case 1 -> position.addAlarm(Position.ALARM_MOVEMENT);
136	                        case 2 -> position.addAlarm(Position.ALARM_FALL_DOWN);
137	                        case 3 -> position.addAlarm(Position.ALARM_LOW_BATTERY);
138	                    }
139	                }
140	                case "E0" -> {
141	                    position.addAlarm(Position.ALARM_FAULT);
142	                    position.set("error", Integer.parseInt(values[index++]));
143	                }
144	                case "S1" -> position.set(Position.KEY_EVENT, Integer.parseInt(values[index++]));
145	                case "R0", "L0", "L1", "S4", "S5", "S6", "S7", "V0", "G0", "K0", "I0", "M0" -> {
146	                    String[] remaining = Arrays.copyOfRange(values, index, values.length);
147	                    position.set(Position.KEY_RESULT, String.join(",", remaining));
148	                }
149	            }
150	
151	            return !position.getAttributes().isEmpty() ? position : null;
152	
153	        } else {
154	
155	            FieldCursor parser = new FieldCursor(PATTERN, sentence);
156	            if (!parser.matches()) {
157	                return null;
158	            }
159	
160	            Position position = new Position(wireName());
161	            position.setDeviceId(deviceSession.getDeviceId());
162	
163	            DateBuilder dateBuilder = new DateBuilder()
164	                    .setTime(parser.nextInt(), parser.nextInt(), parser.nextInt());
165	
166	            position.setValid(parser.next().equals("A"));
167	            position.setLatitude(parser.nextCoordinate());
168	            position.setLongitude(parser.nextCoordinate());
169	
170	            position.set(Position.KEY_SATELLITES, parser.nextInt());
171	            position.set(Position.KEY_HDOP, parser.nextDouble());
172	
173	            dateBuilder.setDateReverse(parser.nextInt(), parser.nextInt(), parser.nextInt());
174	            position.setTime(dateBuilder.getDate());
175	
176	            position.setAltitude(parser.nextDouble());
177	
178	            return position;
179	
180	        }
181	    }
182	
183	}
