    public enum CoordinateFormat {
        DEG_DEG,
        DEG_DEG_HEM,
        WHOLE_DEG_HEMI,
        DEG_MIN_MIN,
        DEG_MIN_HEM,
        DEG_MIN_MIN_HEM,
        HEM_DEG_MIN_MIN,
        HEM_DEG,
        HEM_DEG_MIN,
        HEM_DEG_MIN_HEM
    }

    public double nextCoordinate(CoordinateFormat format) {
        double coordinate;
        String hemisphere = null;

        switch (format) {
            case DEG_DEG:
                coordinate = Double.parseDouble(next() + '.' + next());
                break;
            case DEG_DEG_HEM:
                coordinate = Double.parseDouble(next() + '.' + next());
                hemisphere = next();
                break;
            case WHOLE_DEG_HEMI:
                coordinate = nextDouble(0);
                hemisphere = next();
                break;
            case DEG_MIN_MIN:
                coordinate = nextInt(0);
                coordinate += Double.parseDouble(next() + '.' + next()) / 60;
                break;
            case DEG_MIN_MIN_HEM:
                coordinate = nextInt(0);
                coordinate += Double.parseDouble(next() + '.' + next()) / 60;
                hemisphere = next();
                break;
            case HEM_DEG:
                hemisphere = next();
                coordinate = nextDouble(0);
                break;
            case HEM_DEG_MIN:
                hemisphere = next();
                coordinate = nextInt(0);
                coordinate += nextDouble(0) / 60;
                break;
            case HEM_DEG_MIN_HEM:
                hemisphere = next();
                coordinate = nextInt(0);
                coordinate += nextDouble(0) / 60;
                if (hasNext()) {
                    hemisphere = next();
                }
                break;
            case HEM_DEG_MIN_MIN:
                hemisphere = next();
                coordinate = nextInt(0);
                coordinate += Double.parseDouble(next() + '.' + next()) / 60;
                break;
            case DEG_MIN_HEM:
            default:
                coordinate = nextInt(0);
                coordinate += nextDouble(0) / 60;
                hemisphere = next();
                break;
        }

        if (hemisphere != null && (hemisphere.equals("S") || hemisphere.equals("W") || hemisphere.equals("-"))) {
            coordinate = -Math.abs(coordinate);
        }

        return coordinate;
    }

    public double nextCoordinate() {
        return nextCoordinate(CoordinateFormat.DEG_MIN_HEM);
    }

    public enum DateTimeFormat {
        HMS,
        SMH,
        HMS_YMD,
        HMS_DMY,
        SMH_YMD,
        SMH_DMY,
        DMY_HMS,
        DMY_HMSS,
        YMD_HMS,
        YMD_HMSS,
    }

    public Date nextDateTime(DateTimeFormat format, String timeZone) {
        int year = 0, month = 0, day = 0;
        int hour, minute, second, millisecond = 0;

        switch (format) {
            case HMS:
                hour = nextInt(0);
                minute = nextInt(0);
                second = nextInt(0);
                break;
            case SMH:
                second = nextInt(0);
                minute = nextInt(0);
                hour = nextInt(0);
                break;
            case HMS_YMD:
                hour = nextInt(0);
                minute = nextInt(0);
                second = nextInt(0);
                year = nextInt(0);
                month = nextInt(0);
                day = nextInt(0);
                break;
            case HMS_DMY:
                hour = nextInt(0);
                minute = nextInt(0);
                second = nextInt(0);
                day = nextInt(0);
                month = nextInt(0);
                year = nextInt(0);
                break;
            case SMH_YMD:
                second = nextInt(0);
                minute = nextInt(0);
                hour = nextInt(0);
                year = nextInt(0);
                month = nextInt(0);
                day = nextInt(0);
                break;
            case SMH_DMY:
                second = nextInt(0);
                minute = nextInt(0);
                hour = nextInt(0);
                day = nextInt(0);
                month = nextInt(0);
                year = nextInt(0);
                break;
            case DMY_HMS:
            case DMY_HMSS:
                day = nextInt(0);
                month = nextInt(0);
                year = nextInt(0);
                hour = nextInt(0);
                minute = nextInt(0);
                second = nextInt(0);
                break;
            case YMD_HMS:
            case YMD_HMSS:
            default:
                year = nextInt(0);
                month = nextInt(0);
                day = nextInt(0);
                hour = nextInt(0);
                minute = nextInt(0);
                second = nextInt(0);
                break;
        }

        if (format == DateTimeFormat.YMD_HMSS || format == DateTimeFormat.DMY_HMSS) {
            millisecond = nextInt(0); // (ddd)
        }

        if (year >= 0 && year < 100) {
            year += 2000;
        }

        DateBuilder dateBuilder;
        if (format != DateTimeFormat.HMS && format != DateTimeFormat.SMH) {
            if (timeZone != null) {
                dateBuilder = new DateBuilder(TimeZone.getTimeZone(timeZone));
            } else {
                dateBuilder = new DateBuilder();
            }
            dateBuilder.setDate(year, month, day);
        } else {
            if (timeZone != null) {
                dateBuilder = new DateBuilder(new Date(), TimeZone.getTimeZone(timeZone));
            } else {
                dateBuilder = new DateBuilder(new Date());
            }
        }

        dateBuilder.setTime(hour, minute, second, millisecond);

        return dateBuilder.getDate();
    }

    public Date nextDateTime(DateTimeFormat format) {
        return nextDateTime(format, null);
    }

    public Date nextDateTime() {
        return nextDateTime(DateTimeFormat.YMD_HMS, null);
    }

}

