package org.traccar.helper;

import java.util.ArrayList;
import java.util.regex.Pattern;

public class GrammarComposer {

    private final ArrayList<String> fragments = new ArrayList<>();

    public GrammarComposer optional() {
        return optional(1);
    }

    public GrammarComposer optional(int count) {
        fragments.add(fragments.size() - count, "(?:");
        fragments.add(")?");
        return this;
    }

    public GrammarComposer expression(String s) {
        s = s.replaceAll("\\|$", "\\\\|"); // special case for delimiter

        fragments.add(s);
        return this;
    }

    public GrammarComposer text(String s) {
        fragments.add(s.replaceAll("([\\\\.\\[{()*+?^$|])", "\\\\$1"));
        return this;
    }

    public GrammarComposer number(String s) {
        s = s.replace("dddd", "d{4}").replace("ddd", "d{3}").replace("dd", "d{2}");
        s = s.replace("xxxx", "x{4}").replace("xxx", "x{3}").replace("xx", "x{2}");

        s = s.replace("d", "\\d").replace("x", "[0-9a-fA-F]").replaceAll("([.])", "\\\\$1");
        s = s.replaceAll("\\|$", "\\\\|").replaceAll("^\\|", "\\\\|"); // special case for delimiter

        fragments.add(s);
        return this;
    }

    public GrammarComposer any() {
        fragments.add(".*");
        return this;
    }

    public GrammarComposer binary(String s) {
        fragments.add(s.replaceAll("(\\p{XDigit}{2})", "\\\\$1"));
        return this;
    }

    public GrammarComposer or() {
        fragments.add("|");
        return this;
    }

    public GrammarComposer groupBegin() {
        return expression("(?:");
    }

    public GrammarComposer groupEnd() {
        return expression(")");
    }

    public GrammarComposer groupEnd(String s) {
        return expression(")" + s);
    }

    public Pattern compile() {
        return Pattern.compile(toString(), Pattern.DOTALL);
    }

    @Override
    public String toString() {
        StringBuilder builder = new StringBuilder();
        for (String fragment : fragments) {
            builder.append(fragment);
        }
        return builder.toString();
    }

}

